function TarotBackdrop() {
  return (
    <svg
      className="tarot-bg"
      viewBox="0 0 800 1200"
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
      focusable="false"
    >
      {/*
        星は描かない。
        暗い地に小さな白い点が散っていると、画面の汚れと区別が付かない。
        星として読ませたいのに、拭きたくなる形になっていた。
        端末の埃や気泡と競合しない、無地の地に戻す。
        奥行きは、下地の階調だけで作る。
      */}
    </svg>
  );
}
