    majorCard: { card: majorCardObj, reversed: data.majorReversed },
    minorResults: minorObjs,
    question: data.question || "",
    reading1: data.reading1 || "",
    reading2: data.reading2 || "",
    reading3: data.reading3 || "",
    deepDiveQA: data.deepDiveQA || [],
