/*
  いくつかの県を 0〜100 の枠に収める倍率と寄せ。
  ⚠️ 縦横で別々に伸ばさないこと。倍率は広い方に合わせる。
  ⚠️ 端に余白を残すこと（92）。県名が枠の外へ出る。
*/
function fitBoxes(keys, fill) {
  const bs = keys.map((k) => PREF_BOX[k]).filter(Boolean);
  if (!bs.length) return { k: 1, tx: 0, ty: 0, cx: 0, cy: 0 };
  const x0 = Math.min(...bs.map((b) => b[0])), x1 = Math.max(...bs.map((b) => b[2]));
  const y0 = Math.min(...bs.map((b) => b[1])), y1 = Math.max(...bs.map((b) => b[3]));
  const k = (fill || 92) / Math.max(x1 - x0, y1 - y0, 1);
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  return { k, cx, cy, tx: 50 - cx * k, ty: 50 - cy * k };
}
/** 県の中心を、いまの枠の座標に直す */
function prefAt(pref, fit) {
  const b = PREF_BOX[pref];
  if (!b) return { x: 50, y: 50 };
  return { x: ((b[0] + b[2]) / 2) * fit.k + fit.tx, y: ((b[1] + b[3]) / 2) * fit.k + fit.ty };
}
