function developerNote(majorCard, lang) {
  if (!majorCard || !majorCard.card || !majorCard.card.id) return "";
  const idx = parseInt(majorCard.card.id.split("-")[1], 10);
  const upTable = DEVELOPER_NOTE_UP_I18N[lang] || DEVELOPER_NOTE_UP_I18N.en || DEVELOPER_NOTE_UP_I18N.ja;
  const revTable = DEVELOPER_NOTE_REV_I18N[lang] || DEVELOPER_NOTE_REV_I18N.en || DEVELOPER_NOTE_REV_I18N.ja;
  const table = majorCard.reversed ? revTable : upTable;
  return table[idx] || "";
}
// 「前回の結果を見る」：直近の履歴1件を、新しい占いを始めずにそのまま表示する
/*
  保存した鑑定の一覧。
  ★ ためる場所なので、探せることがすべて。
    百件あっても目当ての回に辿り着けるよう、索引として組む。
  ⚠️ 全文を開いたまま並べないこと。十件でも探せなくなる。
  ⚠️ 削除は取り消せない。番号を打たせて、押し間違いを止める。
*/
/*
  前回の記録の、保存の状態と保存ボタン。
  ★ 「前回」は次に占うと上書きされる。残したい回はここで保存しないと
    失われるので、未保存であることを必ず示す。
  ⚠️ 保存済みのときも黙らないこと。「保存済み」と出ていれば、
    もう一度押す必要が無いと分かる。
*/
function LastSaveBar({ entry, lang }) {
  const base = T[lang] || T.ja;
  const t = new Proxy(base, {
    get: (o, k) => (o[k] !== undefined ? o[k] : (T.ja[k] !== undefined ? T.ja[k] : () => "")),
  });
  const [saved, setSaved] = useState(() => isSaved(entry));
  const [msg, setMsg] = useState("");
  if (!entry || !entry.reading) return null;
  return (
    <div className="last-save">
      <span className={`last-save-state${saved ? " on" : ""}`}>
        {saved ? t.lastSaved : t.lastUnsaved}
      </span>
      {!saved && (
        <>
          <p className="last-save-note">{t.lastUnsavedNote}</p>
          <button type="button" className="multi-btn"
            onClick={() => {
              const ok = addSaved({ ...entry, ts: entry.ts || Date.now() });
              if (ok) { setSaved(true); setMsg(t.savedDone); }
              else setMsg(t.savedFull(savedLimit()));
            }}>
            {t.savedButton}
          </button>
        </>
      )}
      {msg && <p className="last-save-note">{msg}</p>}
    </div>
  );
}
/*
  持ち物。ランドマークカード。
  ⚠️ 0個のものも並べない。名所は 1761 件ある。全部出すと持ち物が探せない。
  ⚠️ 何の札に化けるかを必ず見せる。見えないと、どれを持っていくか決められない。
  ⚠️ どこの名所かも出す。名前だけだと、行った土地と結びつかない。
*/
/*
  持ち物のポケット。
  ★ 名所は78枚のどれかに化けるので、化ける先の札で仕分ける。
    名所の名前で並べても、戦闘で何になるかは分からない。
  ⚠️ 並びは大アルカナ→棒→貨幣→聖杯→剣。札の並びと揃えること。
*/
const ITEM_POCKETS = [
  { suit: "major" }, { suit: "wands" }, { suit: "pentacles" },
  { suit: "cups" }, { suit: "swords" },
];
function ItemPanel({ lang, items, onOpen }) {
  const base = T[lang] || T.ja;
  const t = new Proxy(base, {
    get: (o, k) => (o[k] !== undefined ? o[k] : (T.ja[k] !== undefined ? T.ja[k] : () => "")),
  });
  const a = advT(lang);
  const [msg, setMsg] = useState("");
  const boxes = items.box || 0;
  const cards = items.cards || {};
  /* ⚠️ 持っている数の多い順。同数なら名前順。並びが毎回変わると探せない */
  const held = Object.keys(cards).filter((k) => cards[k] > 0)
    .sort((x, y) => (cards[y] - cards[x]) || x.localeCompare(y, "ja"));
  return (
    <div style={{ width: "100%", maxWidth: "440px", margin: "0 auto" }}>
      <p className="item-note">{t.itemNote(ITEM_FREE_PER_DAY)}</p>
      <p className="item-warn">{t.itemNotYet}</p>
      {/* ⚠️ 抽選は切る瞬間に回る。確率を隠さない */}
      <p className="item-odds">{t.itemSides}</p>
      <details className="tier-odds">
        <summary>{t.itemOddsTitle}</summary>
        <div className="tier-list">
          {LMC_TIERS.map((x) => (
            <div key={x.key} className="tier-row">
              <span className="tier-star">{tierStars(x.key)}</span>
              <span className="tier-name">{t.tierName[x.key]}</span>
              <span className="tier-p">{(x.w / LMC_TIER_TOTAL * 100).toFixed(2)}%</span>
            </div>
          ))}
        </div>
      </details>
      {/* 未開封の箱 */}
      <div className="item-box-row">
        <button type="button" className={`item-box${boxes > 0 ? " ready" : ""}`}
          disabled={!boxes}
          onClick={() => {
            const got = onOpen();
            setMsg(got ? t.itemGot(landmarkCardName(lang, got)) : t.itemEmpty);
          }}>
          <svg viewBox="0 0 24 20" width="52" height="43" aria-hidden="true">
            <path d="M2 8 Q12 1 22 8 L22 10 L2 10 Z" fill="currentColor" opacity="0.95" />
            <rect x="2" y="10" width="20" height="9" rx="1.5" fill="currentColor" opacity="0.8" />
            <rect x="10" y="7" width="4" height="7" rx="1" fill="rgba(20,14,32,0.85)" />
          </svg>
          <span className="item-box-n">{t.itemBoxes(boxes)}</span>
        </button>
        {msg && <p className="item-msg">{msg}</p>}
      </div>
      {/* 持っているカード */}
      {held.length === 0 ? (
        <p className="item-empty">{t.itemCardsNone}</p>
      ) : (
        <>
          <p className="item-count">{t.itemHeld(held.length, held.reduce((s, k) => s + cards[k], 0))}</p>
          {/*
            直近に手に入れた一枚。
            ★ 一番上に、単独で出す。開けた直後に「どこへ入ったか」を探させない。
            ⚠️ ポケットの中にも重複して出す。ここだけにあると、
              時間が経って別のものを引いたときに見失う。
          */}
          {items.last && cards[items.last] > 0 && (() => {
            const c = cardOfLandmark(items.last);
            const w = LANDMARK_WHERE[items.last];
            return (
              <div className="lmc-latest">
                <span className="lmc-latest-tag">{t.itemLatest}</span>
                <span className="lmc-name">{landmarkCardName(lang, items.last)}</span>
                <span className="lmc-where">{w ? `${a.pref[w.pref] || w.pref}・${w.area}` : ""}</span>
                <span className="lmc-card">
                  {t.itemBecomes(c ? getCardName({ ...c, reversed: false }, lang) : "—")}
                </span>
              </div>
            );
          })()}
          {/*
            ポケット。
            ★ 名所は78枚のどれかに化けるので、化ける先の札で仕分ける。
              名所の名前で並べても、戦闘で何になるかは分からない。
            ⚠️⚠️ 空のポケットは出さないこと。5つ並べて中身が1つだけだと、
              持っていないことのほうが目立つ。
            ⚠️ ポケットも札も閉じた状態で始める。開いた状態だと、
              1937件を集めた人の画面が延々と続くことになる。
          */}
          {ITEM_POCKETS.map((p) => {
            const inPocket = held.filter((n) => {
              const c = cardOfLandmark(n);
              return c && String(c.id).split("-")[0] === p.suit;
            });
            if (!inPocket.length) return null;
            /* 札ごとにまとめる。⚠️ 同じ札に化ける名所は一つの札の中へ */
            const byCard = {};
            inPocket.forEach((n) => {
              const c = cardOfLandmark(n);
              (byCard[c.id] = byCard[c.id] || { card: c, names: [] }).names.push(n);
            });
            const cardIds = Object.keys(byCard).sort((x, y) => {
              const nx = Number(String(x).split("-")[1]), ny = Number(String(y).split("-")[1]);
              return nx - ny;
            });
            const total = inPocket.reduce((s, n) => s + cards[n], 0);
            return (
              <details key={p.suit} className="lmc-pocket">
                <summary>
                  {/*
                    ⚠️ 印は DECK_MARKS から引くこと。ここで別の形や色を作ると、
                      盤面の札に出ている印と食い違い、同じスートに二つの顔ができる。
                  */}
                  <span className="lmc-mark" style={{ color: DECK_MARKS[p.suit].color }}>
                    {(() => { const I = DECK_MARKS[p.suit].Icon; return <I size={17} />; })()}
                  </span>
                  <span className="lmc-pocket-name">{t.pocketName[p.suit]}</span>
                  <span className="lmc-pocket-n">{t.pocketCount(cardIds.length, total)}</span>
                </summary>
                {cardIds.map((cid) => {
                  const g = byCard[cid];
                  const n = g.names.reduce((s, x) => s + cards[x], 0);
                  return (
                    <details key={cid} className="lmc-cardgroup">
                      <summary>
                        {/*
                          ⚠️ 角の表記（大アルカナはローマ数字、小アルカナは階位）を出すこと。
                            名前だけだと、棒の3と剣の3が並んだときに見分けが付かない。
                          ⚠️ 色はスートの色。札の印と同じ色で揃える。
                        */}
                        <span className="lmc-corner" style={{ color: DECK_MARKS[p.suit].color }}>
                          {g.card.corner}
                        </span>
                        <span className="lmc-cardgroup-name">
                          {getCardName({ ...g.card, reversed: false }, lang)}
                        </span>
                        <span className="item-n">{n}</span>
                      </summary>
                      {g.names.slice().sort((x, y) => (cards[y] - cards[x]) || x.localeCompare(y, "ja")).map((name) => {
                        const w = LANDMARK_WHERE[name];
                        return (
                          <div key={name} className="lmc-cell">
                            <span className="lmc-name">{landmarkCardName(lang, name)}</span>
                            <span className="lmc-where">
                              {w ? `${a.pref[w.pref] || w.pref}・${w.area}` : ""}
                            </span>
                            <span className="item-n">{cards[name]}</span>
                          </div>
                        );
                      })}
                    </details>
                  );
                })}
              </details>
            );
          })}
        </>
      )}
    </div>
  );
}
function SavedPanel({ lang }) {
  const base = T[lang] || T.ja;
  const t = new Proxy(base, {
    get: (o, k) => (o[k] !== undefined ? o[k] : (T.ja[k] !== undefined ? T.ja[k] : () => "")),
  });
  const [list, setList] = useState(() => loadSaved());
  const [open, setOpen] = useState(null);
  const [sort, setSort] = useState("new");
  const [filter, setFilter] = useState("all");
  /* 削除の確認。⚠️ 打たせる番号は一覧の番号にする。覚えなくて済む */
  const [asking, setAsking] = useState(null);
  const [typed, setTyped] = useState("");
  const lim = savedLimit();
  /* 絞り込みに出す配置。⚠️ 保存があるものだけ出す。空の選択肢は邪魔 */
  const kinds = [...new Set(list.map((x) => x.spread))];
  const shown = list
    .filter((x) => filter === "all" || x.spread === filter)
    .slice()
    .sort((p, q) => (sort === "new" ? q.ts - p.ts : p.ts - q.ts));
  const stamp = (ts) => {
    const d = new Date(ts);
    const p = (n) => String(n).padStart(2, "0");
    /* ⚠️ 秒まで出す。同じ日に何度も引くので、分までだと区別が付かない */
    return `${d.getFullYear()}/${p(d.getMonth() + 1)}/${p(d.getDate())}`
      + ` ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
  };
  return (
    <div style={{ width: "100%", maxWidth: "460px", margin: "0 auto" }}>
      <p className="saved-warn">{t.savedWarn}</p>
      <p className="saved-count">{t.savedCount(list.length, lim)}</p>
      {list.length > 0 && (
        <div className="saved-tools">
          {/* 並べ替え */}
          <div className="saved-row">
            <span className="saved-row-label">{t.savedSort}</span>
            <button type="button" className={`multi-btn${sort === "new" ? " on" : ""}`}
              onClick={() => setSort("new")}>{t.savedNew}</button>
            <button type="button" className={`multi-btn${sort === "old" ? " on" : ""}`}
              onClick={() => setSort("old")}>{t.savedOld}</button>
          </div>
          {/* 配置で絞る。⚠️ 二種類以上あるときだけ出す */}
          {kinds.length > 1 && (
            <div className="saved-row">
              <span className="saved-row-label">{t.savedFilter}</span>
              <button type="button" className={`multi-btn${filter === "all" ? " on" : ""}`}
                onClick={() => setFilter("all")}>{t.savedAll}</button>
              {kinds.map((k) => (
                <button key={k} type="button"
                  className={`multi-btn${filter === k ? " on" : ""}`}
                  onClick={() => setFilter(k)}>
                  {spreadInfo(k, lang).name}
                </button>
              ))}
            </div>
          )}
        </div>
      )}
      {!list.length && <p className="saved-empty">{t.savedEmpty}</p>}
      {shown.map((x, i) => (
        <div key={x.ts} className="saved-item">
          {/*
            索引の行。⚠️ ここを押して開く。
            番号・配置・日時秒を一行に置き、押す範囲を行全体にする。
          */}
          <button type="button" className="saved-head"
            onClick={() => setOpen(open === x.ts ? null : x.ts)}>
            <span className="saved-no">{i + 1}</span>
            <span className="saved-name">{spreadInfo(x.spread, lang).name}</span>
            <span className="saved-time">{stamp(x.ts)}</span>
          </button>
          {x.q && <p className="saved-q">「{x.q}」</p>}
          {open === x.ts ? (
            <>
              <p className="saved-body">{x.reading}</p>
              {/*
                削除。⚠️ 番号を打たせる。押し間違いで消えると取り戻せない。
                ⚠️ 打つ番号は一覧の番号。別の値にすると探しに戻ることになる。
              */}
              {asking === x.ts ? (
                <div className="saved-del">
                  <p className="saved-del-note">{t.savedDelAsk(i + 1)}</p>
                  <input type="text" inputMode="numeric" value={typed}
                    onChange={(e) => setTyped(e.target.value)}
                    className="saved-del-input" />
                  <div className="saved-del-btns">
                    <button type="button" className="back-confirm-yes"
                      disabled={typed.trim() !== String(i + 1)}
                      onClick={() => {
                        removeSaved(x.ts);
                        setList(loadSaved());
                        setAsking(null); setTyped(""); setOpen(null);
                      }}>
                      {t.savedDelete}
                    </button>
                    <button type="button" className="back-confirm-no"
                      onClick={() => { setAsking(null); setTyped(""); }}>
                      {t.confirmBack2}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="saved-btns">
                  <button type="button" className="multi-btn"
                    onClick={() => setOpen(null)}>{t.savedFold}</button>
                  <button type="button" className="multi-btn"
                    onClick={() => { setAsking(x.ts); setTyped(""); }}>
                    {t.savedDelete}
                  </button>
                </div>
              )}
            </>
          ) : (
            <p className="saved-peek">{String(x.reading || "").slice(0, 44)}…</p>
          )}
        </div>
      ))}
    </div>
  );
}
function LastResultPanel({ entry, lang, onClose }) {
  const t = T[lang] || T.ja;
  if (!entry) return null;
  const majorName = entry.majorCard.id
    ? getCardName({ id: entry.majorCard.id, name: entry.majorCard.name }, lang)
    : entry.majorCard.name;
  return (
    <div style={{ width: "100%", maxWidth: "420px", display: "flex", flexDirection: "column", gap: "14px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: "11px", color: "var(--muted)" }}>{entry.date} {entry.time}</span>
        {/*
          ⚠️ 名前だけを置かないこと。「あき」とだけ出ても、
          それが誰の名前で、何のために入力したものか分からない。
          何の欄に書いた値なのかを添える。
        */}
        {entry.userName
          ? <span style={{ fontSize: "11px", color: "var(--gold-soft)" }}>
              {T[lang] && T[lang].lastNameLabel ? T[lang].lastNameLabel : T.ja.lastNameLabel}
              {entry.userName}
            </span>
          : null}
      </div>
      {/*
        何を占った回か。
        ⚠️ 配置名を出すこと。記録を見返す人は、まずどの占いだったかを探す。
        ⚠️ 入力した値も並べる。何を聞いたかが分からないと、
        鑑定文だけ読んでも何の話か分からない。
      */}
      <div className="last-meta">
        <span className="last-meta-spread">{spreadInfo("three", lang).name}</span>
      </div>
      {entry.question && (
        <p style={{ fontSize: "13px", color: "var(--gold-soft)", margin: 0, textAlign: "center" }}>
          「{entry.question}」
        </p>
      )}
      <div style={{ display: "flex", gap: "6px", flexWrap: "wrap", justifyContent: "center" }}>
        {(POSITION_LABELS_I18N[lang] || POSITION_LABELS_I18N.en || POSITION_LABELS).map((pos, i) => {
          const r = entry.minorResults[i];
          if (!r) return null;
          const name = r.id ? getCardName({ id: r.id, name: r.name }, lang) : r.name;
          return (
            <span key={i} style={{ fontSize: "11px", color: "var(--muted)", background: "rgba(201,162,75,0.10)", padding: "3px 9px", borderRadius: "999px" }}>
              {pos}: {name}（{t.historyOrientation(r.reversed)}）
            </span>
          );
        })}
      </div>
      <div style={{ background: "rgba(36,28,77,0.7)", border: "1px solid rgba(201,162,75,0.3)", borderRadius: "12px", padding: "16px 18px", textAlign: "center" }}>
        <p style={{ fontFamily: "'Shippori Mincho',serif", fontSize: "16px", fontWeight: 700, margin: "0 0 6px" }}>
          ✦ {majorName}（{t.historyOrientation(entry.majorCard.reversed)}）
        </p>
        <p style={{ fontSize: "12px", color: "var(--muted)", margin: 0 }}>{entry.majorCard.kw}</p>
      </div>
      <div style={{ background: "rgba(36,28,77,0.6)", border: "1px solid rgba(201,162,75,0.2)", borderRadius: "12px", padding: "12px 14px" }}>
        <div style={{ fontFamily: "Cinzel, serif", fontSize: "10px", letterSpacing: "0.1em", color: "var(--gold)", marginBottom: "8px" }}>
          {t.statsAvgAllTime}
        </div>
        {STAT_CATEGORIES.map((cat, i) => {
          const isMax = entry.scores[i] >= 6;
          const isMin = entry.scores[i] <= 1;
          const variant = isMax ? "max" : isMin ? "min" : null;
          return (
            <div key={cat.key} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "4px 0" }}>
              <span style={{ fontSize: "12px", fontFamily: "'Shippori Mincho',serif", width: "44px", flexShrink: 0 }}>{statLabel(cat.key, lang)}</span>
              <StarRating score={entry.scores[i]} variant={variant} />
              <span style={{ fontSize: "11px", color: isMax ? "var(--star-max)" : isMin ? "var(--star-min)" : "var(--muted)", width: "26px", textAlign: "right" }}>
                {entry.scores[i]}
              </span>
            </div>
          );
        })}
      </div>
      {entry.reading1 && (
        <div className="ai-reading">
          <div className="ai-label"><Sparkles size={12} /> {t.minorReadingLabel}</div>
          <p className="sheen-text">{entry.reading1}</p>
        </div>
      )}
      {entry.reading2 && (
        <div className="ai-reading">
          <div className="ai-label"><Sparkles size={12} /> {t.majorReadingLabel}</div>
          <p className="sheen-text">{entry.reading2}</p>
        </div>
      )}
      {entry.reading3 && (
        <div className="ai-reading final-judgment">
          <div className="ai-label"><Sparkles size={12} /> {t.finalJudgmentLabel}</div>
          <p className="sheen-text">{entry.reading3}</p>
        </div>
      )}
      <p className="privacy-note" style={{ fontSize: "11px", textAlign: "center" }}>
        {t.endOfPrivacyResult}
      </p>
      <button className="reset-btn" onClick={onClose}>
        {t.closeLastResultButton}
      </button>
    </div>
  );
}
/*
  課金診断の表示。
  記録されるのは枠を消費した回だけで、内容は消費・返却・鑑定の成否のみ。
  問いの文面や鑑定文そのものは入れない。状況の再現に要らないうえ、
  問い合わせのために私生活を送らせることになる。
*/
function BillingDiagPanel({ lang }) {
  const t = T[lang] || T.ja;
  const [rows] = useState(() => loadBillingLog());
  const [copied, setCopied] = useState(false);
  const text = formatBillingLog(rows);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch { /* 端末が許さない場合は、下の本文を手で選んでもらう */ }
  };
  return (
    <div className="diag-panel">
      <p className="diag-note"><NoteLines text={t.diagNote} /></p>
      {rows.length === 0 ? (
        <p className="diag-empty">{t.diagEmpty}</p>
      ) : (
        <>
          <button className="draw-btn copy-btn" onClick={copy}>
            {copied ? <Check size={15} /> : <Copy size={15} />}
            {copied ? t.copyDone : t.diagCopy}
          </button>
          <pre className="diag-body">{text}</pre>
        </>
      )}
    </div>
  );
}
function CouponPanel({ couponInput, setCouponInput, handleCoupon, aiEnabled, lang, codeError }) {
  const t = T[lang] || T.ja;
  return (
    <div style={{ width: "100%", maxWidth: "360px", marginTop: "12px", display: "flex", flexDirection: "column", gap: "8px", background: "rgba(36,28,77,0.8)", border: "1px solid rgba(201,162,75,0.3)", borderRadius: "12px", padding: "12px 14px" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "6px", fontSize: "11px", color: aiEnabled ? "var(--star-max)" : "var(--muted)" }}>
        <span style={{ width: "7px", height: "7px", borderRadius: "50%", background: aiEnabled ? "var(--star-max)" : "var(--rose)", display: "inline-block" }} />
        {t.aiStatusLabel}：{aiEnabled ? t.aiStatusOn : t.aiStatusOff}
      </div>
      <p style={{ fontSize: "10px", color: "var(--muted)", margin: 0, textAlign: "center", lineHeight: 1.6, opacity: 0.85 }}>
        {t.couponNote}
      </p>
      <input
        type="text"
        maxLength={64}
        value={couponInput}
        onChange={(e) => setCouponInput(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter") handleCoupon(); }}
        placeholder={t.couponPlaceholder}
        style={{
          fontFamily: "inherit",
          fontSize: "13px",
          padding: "8px 10px",
          borderRadius: "8px",
          border: "1px solid rgba(201,162,75,0.4)",
          background: "rgba(255,255,255,0.04)",
          color: "#f1ead8",
        }}
      />
      <button className="draw-btn" onClick={handleCoupon} style={{ fontSize: "12px", padding: "8px 16px" }}>
        {t.confirmButton}
      </button>
      {codeError && (
        <p style={{ fontSize: "11px", color: "var(--rose)", margin: 0, textAlign: "center" }}>{t.resurrectionError}</p>
      )}
    </div>
  );
}
