const LANG_LABELS = { ja: "日本語", "zh-TW": "繁體中文", en: "English", tl: "Tagalog", th: "ภาษาไทย", id: "Bahasa Indonesia", vi: "Tiếng Việt", ko: "한국어", "zh-CN": "简体中文", ms: "Bahasa Melayu", sv: "Svenska", fr: "Français", es: "Español", it: "Italiano", pt: "Português", ru: "Русский", pl: "Polski", el: "Ελληνικά" };
