    /* 第12便：veredictos, guias, natureza dos caminhos */
    reachTitle: (type, luck) => {
      const name = type === "triple" ? "Trio" : type === "flush" ? "Cor" : "Sequência";
      if (luck === "misfortune") return `${name} à espera — agita-se um mau presságio`;
      if (luck === "neutral") return `${name} à espera`;
      return `${name} à espera — agita-se a fortuna`;
    },
    outcomeTitle: (o) => {
      if (o.kind === "miss") return o.missLuck === "misfortune" ? "Perigo afastado" : o.missLuck === "fortune" ? "Por pouco" : "Não saiu nada";
      return o.roles.map((r) =>
        r.kind === "triple" ? "Trio"
        : r.kind === "flush" ? (
            r.luck === "misfortune"
              ? (r.variant === "void" ? "Cor de ruína total" : "Cor de mau presságio")
              : (r.variant === "holo" ? "Cor no seu auge" : "Cor de bom presságio"))
        : r.dir === "up" ? "Sequência ascendente" : r.dir === "down" ? "Sequência descendente" : "Sequência"
      ).join(" + ");
    },
    outcomeDetail: (o) => {
      if (o.kind === "miss") return o.missLuck === "misfortune" ? "O mau presságio não chegou a formar-se" : o.missLuck === "fortune" ? "Desta vez não se formou nenhuma combinação" : "Não se formou nenhuma combinação especial";
      return o.roles.map((r) =>
        r.kind === "triple" ? `Todas as áreas passam a ★${r.value}`
        : r.kind === "flush" ? (r.blocked ? "Prevaleceu a orientação da carta tema" : `${r.fields.join(" e ")} passam a ★${r.value}`)
        : r.dir === "up" ? "A sorte aproxima-se. Junta-se um ★6"
        : r.dir === "down" ? "O que pesava afasta-se. Junta-se um ★6"
        : "Junta-se um ★6"
      ).join(" / ");
    },
